finding=dict(country='Algeria',country_code='DZA',research_date_utc='2026-11-15',status='complete',market=dict(summary='University libraries offer the strongest observed physical-book entry point. National and wilaya public libraries remain important distinct markets, but this feasibility-selected screen is dominated by institutional collections and does not measure national LMS share. Five selected PMB deployments, one selected SYNGEB deployment, and four individually scoped institutions through CCDZ returned actual book records. National-library digital manuscripts are a partial reserve, not physical-circulation coverage.',platform_strategy='Prioritize a scoped CCDZ adapter for broad bibliographic discovery and a generalized Arabic/French PMB adapter for richer copy statuses; add SYNGEB for public local holdings such as Béjaïa. CCDZ currently proves institution-associated book listings but not live circulation. SNDL subscriptions, PNST theses, repositories and IQRAA ebooks are separate from physical-book holdings.',adoption_evidence=[dict(claim='SYNGEB is CERIST’s bilingual integrated library product, using ISBD/UNIMARC and supporting public and collective catalogs.',scope='Official product capabilities plus observed Béjaïa and UMMTO forms; no current national share estimate.',date='undated product page; live observations2026-11-15',source_url='https://www.dist.cerist.dz/site-syngeb/presentation.php'),dict(claim='Mostaganem says its PMB catalog network has operated since2018.',scope='One university deployment, not national market share.',date='Operational since2018; source read2026-11-15',source_url='https://www.univ-mosta.dz/fst/catalogue-en-ligne/'),dict(claim='Five selected independent university institutions returned PMB book results; four other institutions were verified through scoped CCDZ queries and one through local SYNGEB.',scope='Feasibility-selected10institution sample; not a national adoption survey.',date='2026-11-15',source_url='https://www.ccdz.cerist.dz/')],network_opportunities=[dict(name='CCdz — Catalogue Collectif d’Algérie',scope='National collective catalog; no current exhaustive count established.',source_url='https://www.ccdz.cerist.dz/',verification='Four returned title searches explicitly scoped to not_loc53,124,119,142 establish USTHB,Constantine1,Oran1,Annaba; raw pages retained. No whole-network extra count.',integration_implication='One adapter can serve institution-specific bibliographic answers if source filter semantics are preserved. Require separate circulation source or explicit unknown status.'),dict(name='University PMB / SYNGEB networks',scope='Each university counted once; faculty/room locations are not separate institutions.',source_url='https://www.ummto.dz/le-catalogue-collectif-des-bibliotheques-de-lummto/',verification='Béjaïa local SYNGEB returns scoped physical locations; PMB templates at five selected universities return titles; UMMTO query timed out.',integration_implication='Institution/database identity, transient form state, language handling and copy restrictions must remain intact.'),dict(name='SNDL',scope='National subscribed electronic resources plus links to nationally produced documentary services.',source_url='https://www.dist.cerist.dz/sndl.php',verification='Official description separates campus-access subscriptions and research-user personal accounts; no sign-in attempted.',integration_implication='Cannot substitute for physical holdings, reuse permission or unrestricted public ebook access.')]),major_library_priorities=priorities,libraries=libs,blocked_or_unverified=[dict(name=n,url=u,reason=r,evidence_path=f'evidence/{e}.json') for n,u,r,e in blocked],limitations=['No national largest-ten ranking established; institutional proxies and dated counts use different units/scopes.','Four selected institutions are verified union-catalog associations, not local live circulation checks; record provenance dates can be old.','Mostaganem selected on institution identity, physical copy records and official PMB deployment evidence; _test database naming and source freshness remain explicitly unresolved.','National digital reserve is related-title manuscript metadata, not a general physical OPAC or confirmed viewer entitlement.','Public search is not visitor admission, borrowing eligibility, permission to reuse metadata, or proof of current copy status.','No authentication, outreach, holds, TLS/challenge bypass, harvesting, application edits or live app integration tests.','Failures/zero results never mean the institution does not hold a book; unquoted queries can be broad token matches and accented query echoes can be malformed.','Biskra selected title search works but its detail fetch503; precise copy location/count are unknown.'],sources=sources,counts=dict(selected_physical_institutions=10,reserve_digital_institutions=1,observed_success_institutions=11,selected_platforms={'PMB':5,'SYNGEB':1,'CCdz / CERIST':4}),reproduction='Use saved semantic request metadata. For PMB session probes follow session_query.py: fresh GET, same in-memory cookie jar, public form hidden fields/CSRF, POST title query, then any exposed title-result form. Batna2 requires database=Biblio_Centrale. Do not reuse captured tokens. CCDZ POST payload includes Type_not=a and not_loc institution ID; returned criteria must repeat institution and actual books. No auth or restricted localization endpoint workaround.')
